// Minimal service worker. Its whole purpose is INSTALLABILITY — Chrome's
// install criteria require a registered SW with a fetch handler, and an
// installed home-screen app is what's exempt from Safari's 7-day
// script-writable-storage eviction (see src/localDb.ts, src/device.ts). It
// is deliberately NOT an offline-app-shell cache with a maintained asset
// manifest: Vite's build output is content-hashed per deploy, and this file
// isn't generated by that build, so it has no reliable way to know which
// hashed bundle is current. Trying anyway would risk the classic PWA bug of
// serving a stale index.html/bundle pair forever — see the network-first
// navigation handler below, which exists specifically to avoid that.
//
// /api/* and any other non-GET request are never intercepted: API responses
// are server-authoritative (see manualGrid.ts, device.ts) and stem audio has
// its own IndexedDB cache (see stemEngine.ts) — caching either here would
// create a second, competing cache with no eviction story of its own.

const SHELL_CACHE = 'choreo-shell-v1'
const SHELL_URLS = ['/', '/manifest.webmanifest', '/icon-192.png', '/icon-512.png', '/favicon.svg']

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then((cache) => cache.addAll(SHELL_URLS))
      .catch(() => {
        // Best-effort precache — a failed addAll (one bad URL, or storage
        // unavailable) must not block installation; the fetch handler's
        // network-first path still works with an empty cache, just without
        // an offline fallback until the next successful navigation.
      }),
  )
  self.skipWaiting()
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== SHELL_CACHE).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  )
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return
  if (url.pathname.startsWith('/api/')) return

  // Navigations (loading the app itself): network-first, so a redeployed
  // build is picked up on the very next load. Only falls back to the
  // cached shell when the network request fails outright (actually
  // offline) — a slow-but-successful response is never second-guessed.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone()
          caches.open(SHELL_CACHE).then((cache) => cache.put('/', copy))
          return response
        })
        .catch(() => caches.match('/').then((cached) => cached ?? Response.error())),
    )
    return
  }

  // Everything else (hashed JS/CSS, icons) is left to the browser's own
  // HTTP cache — Vite's content-hashed filenames are already immutable, so
  // there is nothing this SW needs to add, and not intercepting keeps this
  // file from becoming a second source of truth for what's current.
})
